// Parse a Python string literal (repr output) starting at index i in s.
// Returns {value, end}. Handles ' or " quotes, and \\n \\t \\r \\xHH \\uXXXX \\\\ \\' \\" escapes.
export function parsePyStr(s, i) {
  const q = s[i];
  if (q !== "'" && q !== '"') throw new Error('not a string literal at ' + i + ': ' + JSON.stringify(s.slice(i, i + 40)));
  let j = i + 1;
  let out = '';
  while (j < s.length) {
    const c = s[j];
    if (c === '\\') {
      const n = s[j + 1];
      switch (n) {
        case 'n': out += '\n'; j += 2; break;
        case 't': out += '\t'; j += 2; break;
        case 'r': out += '\r'; j += 2; break;
        case 'a': out += ''; j += 2; break;
        case 'b': out += '\b'; j += 2; break;
        case 'f': out += '\f'; j += 2; break;
        case 'v': out += '\v'; j += 2; break;
        case '0': out += '\0'; j += 2; break;
        case '\\': out += '\\'; j += 2; break;
        case "'": out += "'"; j += 2; break;
        case '"': out += '"'; j += 2; break;
        case 'x': out += String.fromCharCode(parseInt(s.substr(j + 2, 2), 16)); j += 4; break;
        case 'u': out += String.fromCharCode(parseInt(s.substr(j + 2, 4), 16)); j += 6; break;
        case 'U': out += String.fromCodePoint(parseInt(s.substr(j + 2, 8), 16)); j += 10; break;
        default: throw new Error('unknown escape \\' + n);
      }
    } else if (c === q) {
      return { value: out, end: j + 1 };
    } else {
      out += c; j++;
    }
  }
  throw new Error('unterminated string');
}

// Extract the value of the 'diff' key from the printed dict, as a real JS string.
// Returns null when there is no 'diff' key. Returns '<EQUAL>' sentinel for {}.
export function diffOf(a, b) {
  const r = run(a, b);
  if (r.code !== 0) return { err: r.err.trim().split('\n').slice(-3).join(' | '), out: r.out };
  const out = r.out;
  if (out.trim() === '{}') return { equal: true };
  const k = out.indexOf("'diff': ");
  if (k === -1) return { diff: null, out };
  const p = parsePyStr(out, k + 8);
  return { diff: p.value, out };
}

// escape a JS string for compact display with \n notation
export function esc(s) {
  if (s === null || s === undefined) return String(s);
  return s.replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/\t/g, '\\t').replace(/\r/g, '\\r');
}

